//! RT core: the Qt-style object model.
//!
//! Landed modules:
//! - `meta`: [`MetaObject`] descriptors generated by `rt-macros`
//! - `registry`: read-only [`Registry`], explicit fill via [`RegistryBuilder`]
//! - `handle`: generational [`Handle`](handle::Handle) identity
//! - `signal`: typed [`Hub`](signal::Hub) — connections, queued delivery, flush
//!
//! Planned modules (each lands with its wayfinder ticket):
//! - `signal`: typed connections, queued-by-default delivery
//! - `property`: [`Property`] values with dirty-flag flush evaluation
//! - `handle`: generational object identity
//!
//! Terms follow `GLOSSARY.md`; decisions live in `docs/adr/`.

#![forbid(unsafe_code)]

pub mod meta;
pub mod handle;
pub mod registry;
pub mod signal;

pub use handle::{ConnectionId, Handle};
pub use meta::{
    MetaObject, Object, ObjectInputs, PropertyDescriptor, SignalDescriptor, SlotDescriptor, TypeRef,
};
pub use registry::{Registry, RegistryBuilder};
pub use rt_macros::{Object, object_impl};
pub use signal::{Hub, SignalId};
